package com.companages.controller; import com.companages.dto.*; import com.companages.dto.ActivityDtos.Response; import com.companages.entity.ActivityAction; import com.companages.service.ActivityService; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestController @RequestMapping("/api/organizations/{organizationId}/activities") public class ActivityController {private final ActivityService service;public ActivityController(ActivityService s){service=s;}@GetMapping PageResponse<Response> list(@PathVariable Long organizationId,@RequestParam(required=false)ActivityAction action,@RequestParam(required=false)Long actorId,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to,@PageableDefault(sort="createdAt",direction=Sort.Direction.DESC)Pageable pageable){return service.list(organizationId,action,actorId,from,to,pageable);}}
